 * visitor onto the edge's address, which turns a per-attacker throttle into a
 * global one — a login lockout for every customer at once.
 */
const TRUSTED_PROXY_HOPS = Math.max(1, Number(process.env.NXEON_TRUSTED_PROXY_HOPS ?? 1) || 1);

/** `unknown` is the shared bucket for callers we cannot place. */
export const UNKNOWN_IP = "unknown";

/**
 * Strip an optional `:port` / `[v6]:port` wrapper and an IPv4-mapped IPv6 prefix
 * so the same peer always produces the same bucket key. `::ffff:127.0.0.1` and
 * `127.0.0.1` are one machine; without this they are two budgets.
 */
function normaliseAddress(value: string): string {
  let v = value.trim();
  if (v.startsWith("[")) {
    const end = v.indexOf("]");
    if (end !== -1) v = v.slice(1, end);
  } else if (v.includes(":") && net.isIP(v) === 0) {
    // host:port for IPv4 (a bare IPv6 has many colons and parses as an IP).
    v = v.split(":")[0];
  }
  const mapped = /^::ffff:((?:\d{1,3}\.){3}\d{1,3})$/i.exec(v);
  return mapped ? mapped[1] : v;
}

/** Anything with a `.get()`: `await headers()`, `req.headers`, or a `Request`. */
type HeaderLike = { get(name: string): string | null };
export type ClientIpSource = HeaderLike | { headers: HeaderLike };

function headersOf(source: ClientIpSource): HeaderLike {
  return typeof (source as HeaderLike)?.get === "function"
    ? (source as HeaderLike)
    : (source as { headers: HeaderLike }).headers;
}

/**
 * The caller's address, for use as a rate-limit key. NEVER attacker-controlled.
 *
 * ── THIS IS THE ONLY DEFINITION ──────────────────────────────────────────────
 *
 * There were two. This one owned the trusted-hop knob; `trustedClientIp` in
 * app/api/_lib/client-ip.ts owned IP-format validation and `::ffff:`/port
 * normalisation. Each was correct about something the other got wrong, they were
 * written days apart from the same incident, and a reader had no way to know
 * which one their call site should use. A second definition of an existing thing
 * is this repo's most common defect class and it caused two production bugs in
 * one week, so the two have been merged here and `trustedClientIp` is now an
 * alias for this function — same code, two names, because ~15 route handlers
 * import it under the second one.
 *
 * Accepts a `Request` as well as a headers object so route handlers and server
 * actions call the same function rather than each growing a wrapper.
 *
 * WHY THIS IS NOT `xff.split(",")[0]`, which is what every call site used to do
 * (and what two route handlers still described in a comment as "the real
 * client"). nginx forwards the header as:
 *
 *     proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;
 *
 * and `$proxy_add_x_forwarded_for` expands to `$http_x_forwarded_for,
 * $remote_addr` — it APPENDS the peer it actually saw to whatever the client
 * sent. So the header this app receives is:
 *
 *     <anything the client typed>, <the client's real address>
 *
 * The LEFTMOST entry is therefore not the client, it is a free-text field the
 * client filled in. Reading it made every limiter keyed on "the IP" evadable by
 * sending a different fake value each request — and that is not a theoretical
 * grading of a header, it was measured: 25 requests through the real nginx with a
 * rotating `X-Forwarded-For` never once tripped a limit that a fixed value trips
 * on the 21st. The same expression keyed the login throttle, so the lockout that
 * is supposed to stop password AND 2FA guessing against a named account stopped
 * nothing. It also keyed the row `POST /api/track` stores as a visitor's IP, so
 * the address in the admin visitor log is whatever the visitor chose to claim.
 *
 * The trustworthy entry is the one NGINX appended: the last one. Everything to
 * its left is client-authored and is discarded. `x-real-ip` (set by the same
 * vhosts with `proxy_set_header X-Real-IP $remote_addr`, which REPLACES rather
 * than appends) is an equally sound second source and is used when no
 * X-Forwarded-For arrives at all.
 *
 * Accepts anything with a `.get()` — `await headers()` from a server action,
 * `req.headers`, or the `Request` itself — so there is ONE definition of "who is
 * calling" rather than a copy per call site that can drift.
 *
 * Every candidate is VALIDATED as an IP before it is returned. A header that is
 * not an address is not an identity, and letting one through means an attacker
 * picks their own bucket name by sending garbage — the same defeat as reading
 * the first hop, one step removed. When nothing checks out the caller falls into
 * the shared `UNKNOWN_IP` bucket, which is conservative rather than private.
 *
 * DEPLOYMENT COUPLING: correct for exactly `TRUSTED_PROXY_HOPS` reverse proxies
 * in front of the app. If a CDN is ever added, raise that env var; the fix is
 * never to go back to reading the leftmost hop.
 */
export function clientIp(source: ClientIpSource): string {
  const h = headersOf(source);
  const hops = (h.get("x-forwarded-for") ?? "")
    .split(",")
    .map((s) => s.trim())
    .filter(Boolean);
  if (hops.length > 0) {
    // Walk back past the proxies we run. Clamped at 0 so a misconfigured hop
    // count degrades to "the leftmost entry" instead of throwing, and keep
    // walking left while the entry is not a valid address — a junk value at the
    // trusted position must not become a bucket key of its own.
    for (let i = Math.max(0, hops.length - TRUSTED_PROXY_HOPS); i >= 0; i--) {
      const candidate = normaliseAddress(hops[i]);
      if (net.isIP(candidate) !== 0) return candidate;
    }
  }
  // `x-real-ip` is set with `proxy_set_header X-Real-IP $remote_addr`, which
  // REPLACES any client value rather than appending — an equally sound source.
  const real = normaliseAddress(h.get("x-real-ip") ?? "");
  if (net.isIP(real) !== 0) return real;
  return UNKNOWN_IP;
}

/**
 * One-shot claim on `key`, valid for `ttlMs`. True the first time, false every
 * time after. Built on the same window store, so it inherits the same
 * single-process caveat documented at the top of this file.
 *
 * Used to make a TOTP code single-use (see lib/totp-verify.ts).
 */
export function claimOnce(key: string, ttlMs: number): boolean {
  return checkRateLimit(`once:${key}`, { max: 1, windowMs: ttlMs }).ok;
}

export function isTrue(v: string | undefined | null): boolean {
  return v === "true" || v === "on" || v === "1";
}

/** Read one setting, falling back to an explicit default then SETTINGS_DEFAULTS. */
export async function getSetting(key: SettingKey | string, fallback?: string): Promise<string> {
  const row = await db.setting.findUnique({ where: { key } });
  if (row) return row.value;
  return fallback ?? SETTINGS_DEFAULTS[key as SettingKey] ?? "";
}

/** Read one setting as a boolean. */
export async function getSettingBool(key: SettingKey | string, fallback = false): Promise<boolean> {
  const row = await db.setting.findUnique({ where: { key } });
  if (row) return isTrue(row.value);
  const def = SETTINGS_DEFAULTS[key as SettingKey];
  return def !== undefined ? isTrue(def) : fallback;
}

/** Read one setting as an integer (cents, days, counts…). */
export async function getSettingInt(key: SettingKey | string, fallback = 0): Promise<number> {
  const raw = await getSetting(key, String(fallback));
  const n = Number(raw);
  return Number.isFinite(n) ? n : fallback;
}

/** Upsert one setting. */
export async function setSetting(key: SettingKey | string, value: string): Promise<void> {
  await db.setting.upsert({
    where: { key },
    update: { value },
    create: { key, value },
  });
}

/**
 * Every setting, with defaults merged under any stored overrides. Secret values
 * ARE included — callers that hand this to the client (the settings page) must
 * strip SECRET_KEYS themselves.
 */
export async function getAllSettings(): Promise<Record<string, string>> {
  const rows = await db.setting.findMany();
  const merged: Record<string, string> = { ...SETTINGS_DEFAULTS };
  for (const r of rows) merged[r.key] = r.value;
  return merged;
}

/**
 * The admin-configured default billing term, in MONTHS, guaranteed to be a term the
 * platform can actually sell.
 *
 * The guarantee is the point. `default_term` was previously the enum
 * "monthly"|"quarterly"|"annual" and the platform's real terms are 1/12/24/36 months
 * (`VPS_TERMS`) — "quarterly" mapped to nothing at all. Anything stored that
 * `VPS_TERMS` does not contain (a legacy row, or a hand-crafted POST that slipped past
 * the panel's enum check) falls back to the first term rather than pre-selecting a
 * commitment no charge path can price. A wizard that pre-selects an unsellable term
 * would fail at `vpsTerm()`'s own silent `?? VPS_TERMS[0]` fallback, charging monthly
 * while the review step displayed something else.
 */
export async function defaultTermMonths(): Promise<number> {
  const months = Number(await getSetting("default_term"));
  return VPS_TERMS.some((t) => t.months === months) ? months : VPS_TERMS[0].months;
}

/**
 * The public support address, guaranteed non-empty.
 *
 * Shared rather than inlined because it is rendered into `mailto:` hrefs on the public
 * contact page. `saveSettings` happily stores a blank string when an operator clears the
 * field, and `mailto:` with no recipient opens an empty compose window — a visitor who
 * clicks "Email our team" would be left with nowhere to send it and no error to explain
 * why. The hardcoded default is the address the marketing site has always published.
 */
export async function supportEmail(): Promise<string> {
  const v = (await getSetting("support_email")).trim();
  return v || SETTINGS_DEFAULTS.support_email;
}

