// Reusable, presentational tax/VAT breakdown line.
//
// Pure (no "use client", no async, no DB): pass the net amount in cents, the tax
// rate as a percent, and the display currency code. Renders Subtotal / Tax /
// Total rows using lib/tax helpers. Callers that need the live rate/currency read
// them from Settings (taxRate(), currentCurrency()) and pass them in — keeping
// this component usable from both server and client trees.
//
// Multi-currency is DISPLAY ONLY (no FX). When taxPercent is 0 the tax row is
// hidden and only the total is shown.

import { applyTax, formatMoney } from "@/lib/tax";

export function TaxLine({
  netCents,
  taxPercent = 0,
  currency = "USD",
  totalLabel = "Total",
  taxLabel = "VAT / Tax",
  netLabel = "Subtotal",
  className = "",
}: {
  netCents: number;
  taxPercent?: number;
  currency?: string;
  totalLabel?: string;
  taxLabel?: string;
  netLabel?: string;
  className?: string;
}) {
  const { net, tax, total } = applyTax(netCents, taxPercent);
  const showTax = taxPercent > 0;

  return (
    <div className={`space-y-1.5 text-sm ${className}`}>
      {showTax && (
        <>
          <div className="flex items-center justify-between text-slate-400">
            <span>{netLabel}</span>
            <span className="font-mono">{formatMoney(net, currency)}</span>
          </div>
          <div className="flex items-center justify-between text-slate-400">
            <span>
              {taxLabel} <span className="text-slate-500">({taxPercent}%)</span>
            </span>
            <span className="font-mono">{formatMoney(tax, currency)}</span>
          </div>
        </>
      )}
      <div className="flex items-center justify-between border-t border-white/[0.06] pt-1.5 font-semibold text-slate-100">
        <span>{totalLabel}</span>
        <span className="font-mono">{formatMoney(total, currency)}</span>
      </div>
    </div>
  );
}
