// Pure currency primitives — symbols, formatting, and DISPLAY-ONLY FX conversion.
//
// This module has NO server dependencies (no db, no settings, no "server-only"),
// so it is safe to import from client components, the edge, server components and
// tests alike. lib/tax.ts re-exports everything here, so existing `@/lib/tax`
// import sites keep working unchanged — the split exists purely so a "use client"
// price component can format money without dragging the Setting store (and Prisma)
// into the browser bundle.
//
// ─────────────────────────────────────────────────────────────────────────────
// DISPLAY vs CHARGE BOUNDARY — the load-bearing invariant of this whole layer.
// ─────────────────────────────────────────────────────────────────────────────
// Prices are stored as integer USD cents and USD is the CHARGE currency: every
// invoice, top-up, wallet balance and provider/registrar cost is denominated and
// settled in USD, and NONE of that is touched here. The helpers below take a
// USD-cents amount and produce a *DISPLAYED* string in a visitor's local currency
// using a configurable rates table — so a euro visitor sees "€4.60" where a US
// visitor sees "$5.00", but both are billed the same $5.00. This is a storefront
// convenience, not multi-currency billing. NEVER feed a converted amount back
// into a charge path.

export type CurrencyMeta = { symbol: string; code: string };

/** Symbol/code map for the currencies we can DISPLAY. */
export const CURRENCIES: Record<string, CurrencyMeta> = {
  USD: { symbol: "$", code: "USD" },
  EUR: { symbol: "€", code: "EUR" },
  GBP: { symbol: "£", code: "GBP" },
  CAD: { symbol: "CA$", code: "CAD" },
  AUD: { symbol: "A$", code: "AUD" },
  NZD: { symbol: "NZ$", code: "NZD" },
  INR: { symbol: "₹", code: "INR" },
  JPY: { symbol: "¥", code: "JPY" },
  CNY: { symbol: "¥", code: "CNY" },
  BRL: { symbol: "R$", code: "BRL" },
  ZAR: { symbol: "R", code: "ZAR" },
  CHF: { symbol: "CHF ", code: "CHF" },
  SEK: { symbol: "kr ", code: "SEK" },
  PLN: { symbol: "zł ", code: "PLN" },
  MXN: { symbol: "MX$", code: "MXN" },
  SGD: { symbol: "S$", code: "SGD" },
  AED: { symbol: "د.إ ", code: "AED" },
};

export const DEFAULT_CURRENCY = "USD";

/** Resolve a currency code to its symbol/code. Unknown codes fall back to `CODE `. */
export function currencyMeta(code: string | undefined | null): CurrencyMeta {
  const key = (code ?? "").trim().toUpperCase();
  return CURRENCIES[key] ?? { symbol: key ? `${key} ` : "$", code: key || DEFAULT_CURRENCY };
}

/**
 * Format integer cents for DISPLAY in the given currency (default USD). Pure and
 * synchronous so client components can use it. No FX conversion is performed —
 * the numeric value is the same regardless of currency; only the symbol changes.
 * (Use `convertAndFormat` when you also want to convert a USD amount.)
 */
export function formatMoney(cents: number, currencyCode: string = DEFAULT_CURRENCY): string {
  const { symbol } = currencyMeta(currencyCode);
  const n = Number.isFinite(cents) ? cents : 0;
  const sign = n < 0 ? "-" : "";
  const value = (Math.abs(n) / 100).toFixed(2);
  return `${sign}${symbol}${value}`;
}

// ---------------- FX conversion (DISPLAY ONLY, card cmsrps03) ----------------

/** Currencies that have NO minor unit (yen etc.) — displayed without decimals. */
export const ZERO_DECIMAL_CURRENCIES = new Set(["JPY"]);

/**
 * Static FX snapshot: target currency units per 1 USD. This is the DEFAULT table
 * — deliberately a coarse, hand-maintained snapshot, NOT a live feed. It exists so
 * conversion works out-of-the-box, but rates drift, so an operator override lives
 * in the `currency_rates` Setting (merged over this map by `parseRatesOverride`).
 * To wire a live source, have a job write fresh JSON into that Setting; nothing
 * here should hardcode a volatile rate at a call site.
 *
 * USD is intentionally present and pinned at 1 — the identity that makes "no
 * conversion" the same code path as "convert".
 */
export const DEFAULT_CURRENCY_RATES: Record<string, number> = {
  USD: 1,
  EUR: 0.92,
  GBP: 0.79,
  CAD: 1.36,
  AUD: 1.52,
  NZD: 1.65,
  INR: 83,
  JPY: 150,
  CNY: 7.2,
  BRL: 5.1,
  ZAR: 18.5,
  CHF: 0.88,
  SEK: 10.6,
  PLN: 4.0,
  MXN: 17.0,
  SGD: 1.34,
  AED: 3.67,
};

/**
 * Merge an admin JSON override (the `currency_rates` Setting) over the default
 * rate table. Pure and defensive: unparseable JSON, non-object payloads, unknown
 * currency codes, and non-positive / non-finite rates are all ignored, so a
 * fat-fingered override can only fail *safe* (fall back to the default rate),
 * never zero out or invert a price. USD is always pinned to 1.
 */
export function parseRatesOverride(json: string | null | undefined): Record<string, number> {
  const rates: Record<string, number> = { ...DEFAULT_CURRENCY_RATES };
  if (json && json.trim()) {
    try {
      const parsed = JSON.parse(json) as unknown;
      if (parsed && typeof parsed === "object" && !Array.isArray(parsed)) {
        for (const [k, v] of Object.entries(parsed as Record<string, unknown>)) {
          const code = k.trim().toUpperCase();
          const rate = typeof v === "number" ? v : Number(v);
          if (CURRENCIES[code] && Number.isFinite(rate) && rate > 0) rates[code] = rate;
        }
      }
    } catch {
      // Malformed override → defaults only. Never throws.
    }
  }
  rates.USD = 1;
  return rates;
}

/** Look up a currency's rate, defaulting to 1 (USD parity) for anything unknown. */
export function rateFor(rates: Record<string, number>, currencyCode: string): number {
  const r = rates?.[(currencyCode || "").toUpperCase()];
  return Number.isFinite(r) && r > 0 ? r : 1;
}

/**
 * Convert an integer USD-cents amount into the target currency's minor units
 * (hundredths) at `rate` (target units per USD). Pure. `rate = 1` is the identity.
 */
export function convertCents(baseUsdCents: number, rate: number): number {
  const n = Number.isFinite(baseUsdCents) ? baseUsdCents : 0;
  const r = Number.isFinite(rate) && rate > 0 ? rate : 1;
  return Math.round(n * r);
}

/**
 * Convert a USD-cents amount and format it for DISPLAY in `currencyCode`.
 *
 * The single entry point the storefront should use to show a localized price.
 * `rate` is target-units-per-USD (pass `rateFor(rates, code)`); omit it (or pass
 * a USD rate of 1) and this reduces exactly to `formatMoney(baseUsdCents, code)`.
 * Zero-decimal currencies (JPY) render without a fractional part. Does NOT change
 * the charge — see the boundary note above.
 */
export function convertAndFormat(
  baseUsdCents: number,
  currencyCode: string = DEFAULT_CURRENCY,
  rate: number = 1,
): string {
  const code = (currencyCode || DEFAULT_CURRENCY).toUpperCase();
  const { symbol } = currencyMeta(code);
  const converted = convertCents(baseUsdCents, rate);
  const sign = converted < 0 ? "-" : "";
  const abs = Math.abs(converted);
  const value = ZERO_DECIMAL_CURRENCIES.has(code)
    ? String(Math.round(abs / 100))
    : (abs / 100).toFixed(2);
  return `${sign}${symbol}${value}`;
}

